import assert from 'node:assert/strict';
import { NoteStore } from '../src/note-store.ts';

test('add returns the note', () => {
  const r = new NoteStore().add('a', 'b');
  assert.equal(r.ok, true);
});

test('add rejects empty title with an error result', () => {
  const r = new NoteStore().add(' ', 'b');
  assert.deepEqual(r, { ok: false, error: 'title required' });
});

test('get unknown id is an error result, not a throw', () => {
  assert.equal(new NoteStore().get(9).ok, false);
