import { parseNoteInput } from './parse-note-input.ts';

export interface RouteRequest { method: string; path: string; query: URLSearchParams; body: string }
export interface RouteResponse { status: number; payload: unknown }

const NOT_FOUND: RouteResponse = { status: 404, payload: { error: 'not found' } };

function createNote(store: NoteStore, req: RouteRequest): RouteResponse {
  const input = parseNoteInput(req.body);
  if (!input.ok) return { status: 400, payload: { error: input.error } };
  const added = store.add(input.value.title, input.value.body);
  if (!added.ok) return { status: 400, payload: { error: added.error } };
  return { status: 201, payload: added.value };
}

function listNotes(store: NoteStore): RouteResponse {
  return { status: 200, payload: store.list() };
}

function getNote(store: NoteStore, rawId: string): RouteResponse {
  if (!/^[1-9][0-9]*$/.test(rawId)) return NOT_FOUND;
  const found = store.get(Number(rawId));
  return found.ok ? { status: 200, payload: found.value } : NOT_FOUND;
}

export function route(store: NoteStore, req: RouteRequest): RouteResponse {
  if (req.path === '/notes') {
    if (req.method === 'POST') return createNote(store, req);
    if (req.method === 'GET') return listNotes(store);
    return NOT_FOUND;
  }
  const m = /^\/notes\/([^/]+)$/.exec(req.path);
  if (m && req.method === 'GET') return getNote(store, m[1]);
  return NOT_FOUND;
}
import type { Note } from './note-store.ts';
import { type Result, ok, err } from './result.ts';

export function searchNotes(notes: Note[], term: string): Result<Note[]> {
  if (!term) return err('term required');
  const t = term.toLowerCase();
  return ok(notes.filter((n) => n.title.toLowerCase().includes(t) || n.body.toLowerCase().includes(t)));
}
import http from 'node:http';
import type { NoteStore } from './note-store.ts';
import { route } from './routes.ts';

function readBody(req: http.IncomingMessage): Promise<string> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    req.on('data', (c: Buffer) => chunks.push(c));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', () => resolve(''));
  });
}

export function createApp(store: NoteStore): http.Server {
  return http.createServer(async (req, res) => {
    const url = new URL(req.url ?? '/', 'http://localhost');
    const body = await readBody(req);
    const out = route(store, { method: req.method ?? 'GET', path: url.pathname, query: url.searchParams, body });
    res.writeHead(out.status, { 'content-type': 'application/json' });
    res.end(JSON.stringify(out.payload));
  });
}
