import assert from 'node:assert/strict';
import type { AddressInfo } from 'node:net';
import { NoteStore } from '../src/note-store.ts';
import { createApp } from '../src/server.ts';

async function withApp<T>(store: NoteStore, fn: (url: string) => Promise<T>): Promise<T> {
  const server = createApp(store);
  await new Promise<void>((r) => server.listen(0, '127.0.0.1', r));
  try {
    return await fn(`http://127.0.0.1:${(server.address() as AddressInfo).port}`);
  } finally {
    server.close();
    server.closeAllConnections();
  }
}

const LOG_LINE = /^(GET|POST|PUT|DELETE) \/\S* \d{3} \d+(\.\d+)?ms$/;

async function captureStdout(fn: () => Promise<void>): Promise<string[]> {
  const orig = process.stdout.write;
  const captured: string[] = [];
  process.stdout.write = ((chunk: string | Uint8Array): boolean => {
    if (typeof chunk === 'string') captured.push(chunk); // ignore the runner's binary events
    return true;
  }) as typeof process.stdout.write;
  try {
    await fn();
    await new Promise((r) => setTimeout(r, 50));
  } finally {
    process.stdout.write = orig;
  }
  return captured.join('').split('\n').filter((l) => l.length > 0);
}

test('AC-11 each request logs exactly one line without the body or query', async () => {
  await withApp(new NoteStore(), async (url) => {
    const lines = await captureStdout(async () => {
      await fetch(`${url}/notes`, { method: 'POST', body: JSON.stringify({ title: 'SECRET-TITLE', body: 'SECRET-BODY' }) });
      await fetch(`${url}/search?q=SECRET-QUERY`);
    });
    assert.equal(lines.length, 2, lines.join('|'));
    assert.match(lines[0], LOG_LINE);
    assert.ok(lines[0].startsWith('POST /notes 201 '));
    assert.ok(lines[1].startsWith('GET /search 200 '));
    assert.match(lines[1], LOG_LINE);
    for (const l of lines) assert.ok(!l.includes('SECRET'), l);
  });
});

test('AC-15 p95 latency under 50ms per endpoint with 1000 notes', async () => {
  const store = new NoteStore();
  for (let i = 0; i < 1000; i++) store.add(`title ${i}`, `body ${i}`);
  await withApp(store, async (url) => {
    const cases: Array<[string, string, RequestInit?]> = [
      ['POST /notes', '/notes', { method: 'POST', body: JSON.stringify({ title: 't', body: 'b' }) }],
      ['GET /notes', '/notes'],
      ['GET /notes/:id', '/notes/500'],
      ['GET /search', '/search?q=title'],
      ['GET /health', '/health'],
    ];
    const orig = process.stdout.write;
    process.stdout.write = (() => true) as typeof process.stdout.write;
    const failures: string[] = [];
    try {
      for (const [name, path, init] of cases) {
        const times: number[] = [];
        for (let i = 0; i < 100; i++) {
          const t0 = performance.now();
          const res = await fetch(url + path, init);
          await res.text();
          times.push(performance.now() - t0);
        }
        times.sort((a, b) => a - b);
        const p95 = times[Math.ceil(times.length * 0.95) - 1];
        if (!(p95 < 50)) failures.push(`${name} p95=${p95}`);
      }
    } finally {
      process.stdout.write = orig;
    }
    assert.deepEqual(failures, []);
  });
});

test('AC-13 gate: lint and typecheck exit 0', async () => {
  const { spawnSync } = await import('node:child_process');
  for (const args of [['run', 'lint'], ['exec', '--', 'tsc', '--noEmit']]) {
    const r = spawnSync('npm', args, { encoding: 'utf8' });
    assert.equal(r.status, 0, r.stdout + r.stderr);
  }
});
